mapper.update:
UPDATE sys_plugin_build SET phase = #{build.phase}, lease_expires_time = #{build.leaseExpiresTime},
    update_time = #{now}
WHERE tenant_id = #{build.tenantId} AND id = #{build.id} AND del_flag = 0
    AND worker_id = #{build.workerId} AND lease_hash = #{build.leaseHash}
    AND phase = #{previousPhase} AND finished_time IS NULL
    AND lease_expires_time > #{now} AND deadline_time > #{now}

UPDATE sys_plugin_build SET phase = #{build.phase}, finished_time = #{now},
    result_json = #{build.resultJson}, result_sha256 = #{build.resultSha256}, update_time = #{now}
WHERE tenant_id = #{build.tenantId} AND id = #{build.id} AND del_flag = 0
    AND worker_id = #{build.workerId} AND lease_hash = #{build.leaseHash} AND finished_time IS NULL
    AND phase = #{previousPhase}
    AND lease_expires_time > #{now} AND deadline_time > #{now}
